examples.config:
Storage {
  Name = "File"
}

Storage {
  Name = File
  Description = "Disk storage in the server room"
}

Storage {
  Name = File
  Protocol = Native
}

Storage {
  Name = File
  Auth Type = None
}

Storage {
  Name = File
  Address = "backup.example.com"
}

Storage {
  Name = File
  Lan Address = "10.0.0.5"
}

Storage {
  Name = File
  Port = 9103
}

Storage {
  Name = File
  Username = "ndmp"
}

Storage {
  Name = File
  Password = "storage-secret"
}

Storage {
  Name = File
  Device = "FileStorage"
}

Storage {
  Name = File
  Media Type = "File"
}

Storage {
  Name = File
  Auto Changer = yes
}

Storage {
  Name = File
  Enabled = yes
}

Storage {
  Name = File
  Allow Compression = yes
}

Storage {
  Name = File
  Heartbeat Interval = 60
}

Storage {
  Name = File
  Cache Status Interval = 30
}

Storage {
  Name = File
  Maximum Concurrent Jobs = 10
}

Storage {
  Name = File
  Maximum Concurrent Read Jobs = 2
}

Storage {
  Name = File
  Paired Storage = "File"
}

Storage {
  Name = File
  Maximum Bandwidth Per Job = 50 m/s
}

Storage {
  Name = File
  Collect Statistics = no
}

Storage {
  Name = File
  NDMP Changer Device = "/dev/sg0"
}

Storage {
  Name = File
  TLS Authenticate = no
}

Storage {
  Name = File
  TLS Enable = yes
}

Storage {
  Name = File
  TLS Require = yes
}

Storage {
  Name = File
  TLS Cipher List = "PSK-AES256-GCM-SHA384:PSK-AES128-GCM-SHA256"
}

Storage {
  Name = File
  TLS Cipher Suites = "TLS_AES_256_GCM_SHA384:TLS_CHACHA20_POLY1305_SHA256"
}

Storage {
  Name = File
  TLS DH File = "/etc/bareos/tls/dh2048.pem"
}

Storage {
  Name = File
  TLS Protocol = "-ALL, +TLSv1.2, +TLSv1.3"
}

Storage {
  Name = File
  TLS Verify Peer = yes
}

Storage {
  Name = File
  TLS Ca Certificate File = "/etc/bareos/tls/ca.pem"
}

Storage {
  Name = File
  TLS Ca Certificate Dir = "/etc/ssl/certs"
}

Storage {
  Name = File
  TLS Certificate Revocation List = "/etc/bareos/tls/crl.pem"
}

Storage {
  Name = File
  TLS Certificate = "/etc/bareos/tls/bareos-dir.pem"
}

Storage {
  Name = File
  TLS Key = "/etc/bareos/tls/bareos-dir.key"
}

Storage {
  Name = File
  TLS Allowed CN = "client1.example.com"
}
